function taskEditModal(task=null,eventId=S.selectedEvent,parentId=null){let e=eventBy(eventId),manager=canManageEvent(eventId);if(!manager)return;let selected=task?taskPeople(task.id):[];let pool=eventMembers(eventId).map(m=>m.person_id);if(!pool.length)pool=S.people.map(p=>p.id);let nowMonth=`${new Date().getFullYear()}-${String(new Date().getMonth()+1).padStart(2,'0')}-01`;modal(`${sheetHead(task?'Editar tarea':'Nueva tarea',e?.name||'')}<form class="form" id="taskForm"><div class="formRow"><div class="field"><label>Nombre</label><input name="title" value="${esc(task?.title||'')}" required></div><div class="field"><label>Tipo</label><select name="type"><option value="simple" ${task?.task_type==='simple'?'selected':''}>Simple</option><option value="complex" ${task?.task_type==='complex'?'selected':''}>Compleja</option></select></div></div><div class="formRow three"><div class="field"><label>Prioridad</label><select name="priority">${['low','medium','high'].map(x=>`<option value="${x}" ${task?.priority===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Fecha límite</label><input type="datetime-local" name="due" value="${task?.due_at?U.dateKey(task.due_at)+'T'+U.time(task.due_at):''}"></div><div class="field"><label>Presupuesto estimado</label><input type="number" name="budget" min="0" step="1" value="${esc(task?.budget_estimated||'')}"></div></div><div class="field"><label>Descripción / planificación</label><textarea name="description">${esc(task?.description||'')}</textarea></div><div class="field"><label>Materiales necesarios</label><textarea name="materials">${esc(task?.materials||'')}</textarea></div><div class="field"><label>Responsables</label><div class="checkList">${pool.map(pid=>{let w=workloadFor(pid),av=e?.start_date?S.availability.find(a=>a.person_id===pid&&a.date===e.start_date):null;return `<label class="checkRow"><input type="checkbox" name="assignee" value="${pid}" ${selected.includes(pid)?'checked':''}>${avatarHtml(pid)}<span>${esc(displayName(pid))}${av?.status==='unavailable'?'<div class="dangerText tiny">No disponible ese día</div>':av?.status==='maybe'?'<div class="tiny">Disponibilidad dudosa</div>':''}</span><small>${w} asign. este mes</small></label>`}).join('')}</div></div><button class="btn primary">Guardar tarea</button></form>`,true);$('#taskForm').onsubmit=async ev=>{ev.preventDefault();let f=new FormData(ev.target),payload={event_id:eventId,parent_task_id:parentId||task?.parent_task_id||null,title:f.get('title'),task_type:f.get('type'),priority:f.get('priority'),description:f.get('description')||null,materials:f.get('materials')||null,due_at:f.get('due')?new Date(f.get('due')).toISOString():null,budget_estimated:Number(f.get('budget'))||null,created_by:task?.created_by||currentPersonId(),sort_order:task?.sort_order??S.tasks.filter(t=>t.event_id===eventId).length};let id=task?.id;if(task){let u=await sb.from('tnt_tasks').update(payload).eq('id',id);if(u.error)return toast(errMsg(u.error))}else{let ins=await sb.from('tnt_tasks').insert(payload).select().single();if(ins.error)return toast(errMsg(ins.error));id=ins.data.id}let ids=f.getAll('assignee'),old=S.assignees.filter(a=>a.task_id===id),oldIds=old.map(a=>a.person_id);let remove=oldIds.filter(x=>!ids.includes(x));if(remove.length){const rr=await sb.from('tnt_task_assignees').delete().eq('task_id',id).in('person_id',remove);if(rr.error)return toast(errMsg(rr.error));}let add=ids.filter(x=>!oldIds.includes(x));if(add.length){let rr=await sb.from('tnt_task_assignees').insert(add.map(person_id=>({task_id:id,person_id})));if(rr.error)return toast(errMsg(rr.error))}closeModal();await loadAll();toast('Tarea guardada');taskDetailModal(id)}}



