async function taskDetailModal(id){let t=taskBy(id),e=eventBy(t?.event_id);if(!t||!e)return;let manager=canManageEvent(e.id),mine=myAssignment(t);let [linksR,checkR,commentsR,filesR,privateR]=await Promise.all([sb.from('tnt_task_links').select('*').eq('task_id',id).order('sort_order'),sb.from('tnt_task_checklist').select('*').eq('task_id',id).order('sort_order'),sb.from('tnt_task_comments').select('*').eq('task_id',id).order('created_at'),sb.from('tnt_task_files').select('*').eq('task_id',id).order('created_at'),manager?sb.from('tnt_task_private_notes').select('*').eq('task_id',id).order('created_at'):Promise.resolve({data:[]})]);let links=linksR.data||[],checks=checkR.data||[],comments=commentsR.data||[],files=filesR.data||[],priv=privateR.data||[],assign=S.assignees.filter(a=>a.task_id===id);modal(`${sheetHead(t.title,e.name)}<div class="chips">${statusChip(t.status)}<span class="chip priority ${esc(t.priority)}">Prioridad ${esc(t.priority)}</span>${t.due_at?`<span class="chip">Vence ${new Date(t.due_at).toLocaleString('es-AR')}</span>`:''}</div><div class="grid g2" style="margin-top:13px"><div class="card"><h3>Responsables</h3>${assign.length?`<div class="responsibles">${assign.map(a=>`<button class="personLink" data-person-open="${a.person_id}">${avatarHtml(a.person_id)} ${esc(displayName(a.person_id))} · ${esc(ASSIGN_LABEL[a.assignment_status])}</button>`).join('')}</div>`:'<p>Sin responsables</p>'}</div><div class="card"><h3>Planificación</h3><p>${esc(t.description||'Sin descripción')}</p>${t.materials?`<p><b>Materiales:</b> ${esc(t.materials)}</p>`:''}${t.budget_estimated?`<p><b>Presupuesto:</b> $${Number(t.budget_estimated).toLocaleString('es-AR')}</p>`:''}</div></div>${mine?`<div class="card" style="margin-top:12px"><h3>Tu asignación</h3><p>${esc(ASSIGN_LABEL[mine.assignment_status])}${mine.response_note?' · '+esc(mine.response_note):''}</p><div class="actions" style="margin-top:10px">${mine.assignment_status==='assigned'?'<button class="btn" data-response="read">Marcar leído</button>':''}${mine.assignment_status!=='accepted'?'<button class="btn good" data-response="accepted">Acepto</button>':''}${mine.assignment_status!=='declined'?'<button class="btn danger" data-response="declined">No puedo hacerlo</button>':''}</div></div>`:''}${manager||mine?`<div class="sectionHead"><h2>Estado</h2></div><div class="actions">${['unread','preparing','progress','review','ready','completed'].map(s=>`<button class="btn small ${t.status===s?'primary':''}" data-task-status="${s}">${esc(STATUS_LABEL[s])}</button>`).join('')}</div>`:''}<div class="sectionHead"><h2>Checklist</h2>${manager||mine?'<button class="btn small" id="addCheck">+ Punto</button>':''}</div>${checks.length?`<div class="checkList">${checks.map(c=>`<label class="checkRow"><input type="checkbox" data-check-id="${c.id}" ${c.done?'checked':''}><span style="${c.done?'text-decoration:line-through;color:var(--muted)':''}">${esc(c.text)}</span>${c.assigned_person_id?`<small>${esc(displayName(c.assigned_person_id))}</small>`:''}</label>`).join('')}</div>`:empty('Sin checklist','')}<div class="sectionHead"><h2>Referencias</h2>${manager||mine?'<button class="btn small" id="addLink">+ Link</button>':''}</div><div class="grid">${links.map(linkCard).join('')||empty('Sin links','')}</div><div class="sectionHead"><h2>Archivos</h2>${manager||mine?'<label class="btn small">+ Archivo<input id="taskFile" type="file" hidden></label>':''}</div><div class="actions">${files.map(f=>`<button class="fileBtn" data-open-file="${f.id}" data-file-path="${esc(f.storage_path)}">📎 ${esc(f.file_name)}</button>`).join('')||'<span class="tiny">Sin archivos</span>'}</div><div class="sectionHead"><h2>Comentarios</h2></div>${comments.map(c=>`<div class="comment"><b>${esc(displayName(c.person_id))}</b><p>${esc(c.body)}</p></div>`).join('')||'<div class="tiny">Sin comentarios</div>'}<form class="form" id="commentForm" style="margin-top:10px"><div class="field"><textarea name="body" placeholder="Escribir comentario"></textarea></div><button class="btn">Comentar</button></form>${manager?`<div class="sectionHead"><h2>Notas privadas de organizadores</h2><button class="btn small" id="addPrivate">+ Nota privada</button></div>${priv.map(n=>`<div class="comment privateNote"><b>${esc(displayName(n.author_person_id))}</b><p>${esc(n.body)}</p></div>`).join('')||'<div class="tiny">Sin notas privadas</div>'}`:''}<div class="sectionHead"><h2>Subtareas</h2>${manager?'<button class="btn small" id="addSubtask">+ Subtarea</button>':''}</div>${childrenOf(id).length?`<div class="list">${childrenOf(id).map(x=>taskRow(x,myAssignment(x))).join('')}</div>`:'<div class="tiny">Sin subtareas</div>'}${manager?`<div class="actions" style="margin-top:16px"><button class="btn" id="editTask">Editar tarea</button><button class="btn danger" id="deleteTask">Eliminar</button></div>`:''}`,true);
  $$('[data-person-open]').forEach(b=>b.onclick=()=>personResponsibilitiesModal(b.dataset.personOpen));$$('[data-task-open]').forEach(b=>b.onclick=()=>taskDetailModal(b.dataset.taskOpen));$$('[data-response]').forEach(b=>b.onclick=()=>assignmentResponse(id,b.dataset.response));$$('[data-task-status]').forEach(b=>b.onclick=()=>setTaskStatus(id,b.dataset.taskStatus));$$('[data-check-id]').forEach(c=>c.onchange=()=>toggleCheck(c.dataset.checkId,c.checked));$$('[data-open-file]').forEach(b=>b.onclick=()=>openTaskFile(b.dataset.filePath));
  $('#commentForm').onsubmit=async ev=>{ev.preventDefault();let body=new FormData(ev.target).get('body')?.trim();if(!body)return;let {error}=await sb.from('tnt_task_comments').insert({task_id:id,person_id:currentPersonId(),body});if(error)return toast(errMsg(error));taskDetailModal(id)};
  $('#addCheck')?.addEventListener('click',()=>addChecklistModal(id,checks.length));$('#addLink')?.addEventListener('click',()=>addLinkModal(id,links.length));$('#taskFile')?.addEventListener('change',e2=>uploadTaskFile(id,e2.target.files?.[0]));$('#addPrivate')?.addEventListener('click',()=>addPrivateNoteModal(id));$('#addSubtask')?.addEventListener('click',()=>taskEditModal(null,e.id,id));$('#editTask')?.addEventListener('click',()=>taskEditModal(t,e.id));$('#deleteTask')?.addEventListener('click',async()=>{if(!confirm('¿Eliminar esta tarea y sus subtareas?'))return;let {error}=await sb.from('tnt_tasks').delete().eq('id',id);if(error)return toast(errMsg(error));closeModal();await loadAll();render()})
}


