function profileModal(pid=currentPersonId(),isNew=false){let p=pid?pBy(pid):null,a=pid?aByPid(pid):null,self=pid===currentPersonId(),roleEdit=isAdmin();let prefs=a?.service_preferences||{};modal(`${sheetHead(isNew?'Nuevo perfil':'Perfil TNT',isNew?'Podés precargar el email antes de que la persona ingrese con Google.':'Datos centrales compartibles con otros módulos')}<form class="form" id="profileForm"><div class="profileHero">${p?avatarHtml(p.id):'<div class="avatar">+</div>'}<div><b>${esc(a?.nickname||p?.full_name||'Nuevo perfil')}</b><div class="tiny">${esc(a?.system_role==='admin'?'Admin · '+a?.ministry_role:a?.ministry_role||'')}</div></div>${p&&(self||isAdmin())?'<label class="btn small">Cambiar foto<input id="avatarFile" type="file" accept="image/*" hidden></label>':''}</div><div class="formRow"><div class="field"><label>Nombre completo</label><input name="name" value="${esc(p?.full_name||'')}" required></div><div class="field"><label>Sobrenombre</label><input name="nick" value="${esc(a?.nickname||'')}"></div></div><div class="formRow three"><div class="field"><label>Fecha de nacimiento</label><input type="date" name="birthday" value="${esc(p?.birthday||'')}"></div><div class="field"><label>Sexo confirmado</label><select name="sex"><option value="U" ${p?.sex==='U'?'selected':''}>Sin confirmar</option><option value="F" ${p?.sex==='F'?'selected':''}>Femenino</option><option value="M" ${p?.sex==='M'?'selected':''}>Masculino</option></select></div><div class="field"><label>WhatsApp / teléfono</label><input name="phone" value="${esc(p?.phone||'')}"></div></div><div class="field"><label>Email de cuenta</label><input type="email" name="email" value="${esc(a?.email||'')}"></div>${roleEdit?`<div class="field"><label>Rol TNT</label><select name="role">${ROLE_OPTIONS.map(r=>`<option value="${r}" ${a?.ministry_role===r?'selected':''}>${r}</option>`).join('')}</select></div>`:''}<div class="field"><label>Áreas en las que sirve / le gusta servir</label><div class="checkList">${SERVICE_AREAS.map(x=>`<label class="checkRow"><input type="checkbox" name="area" value="${esc(x)}" ${a?.service_areas?.includes(x)?'checked':''}><span>${esc(x)}</span><select name="pref_${esc(x)}"><option value="neutral" ${(prefs[x]||'neutral')==='neutral'?'selected':''}>Me da igual</option><option value="love" ${prefs[x]==='love'?'selected':''}>Me encanta</option><option value="avoid" ${prefs[x]==='avoid'?'selected':''}>Prefiero no hacerlo</option></select></label>`).join('')}</div></div><div class="field"><label>Talentos / habilidades</label><input name="skills" value="${esc((a?.skills||[]).join(', '))}" placeholder="Fotografía, video, diseño"></div><div class="field"><label>Disponibilidad habitual</label><input name="days" value="${esc((a?.availability_days||[]).join(', '))}" placeholder="Sábados, Miércoles"></div><div class="field"><label>Sobre mí</label><textarea name="bio">${esc(a?.bio||'')}</textarea></div><div class="field"><label>Información personal extra (opcional)</label><textarea name="extra" placeholder="Campo: valor, uno por línea">${esc(Object.entries(a?.profile_extra||{}).map(([k,v])=>`${k}: ${v}`).join('\n'))}</textarea></div><button class="btn primary">Guardar perfil</button></form>`,true);
  $('#avatarFile')?.addEventListener('change',e=>uploadAvatar(pid,e.target.files?.[0]));$('#profileForm').onsubmit=async ev=>{ev.preventDefault();let f=new FormData(ev.target),personPayload={full_name:String(f.get('name')).trim(),normalized_name:String(f.get('name')).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,''),birthday:f.get('birthday')||null,sex:f.get('sex')||'U',phone:f.get('phone')||null,source:p?.source||'organizacion',active:true};let personId=pid;if(isNew){let ins=await sb.from('tnt_people').insert(personLayload).select().single();if(ins.error)return toast(errMsg(ins.error));personId=ins.data.id}else{let u=await sb.from('tnt_people').update(personPayload).eq('id',personId);if(u.error)return toast(errMsg(u.error))}let pref={};SERVICE_AREAS.forEach(x=>pref[x]=f.get('pref_'+x)||'neutral');let extra={};String(f.get('extra')||'').split(/\n+/).forEach(line=>{let i=line.indexOf(':');if(i>0)extra[line.slice(0,i).trim()]=line.slice(i+1).trim()});let accountPayload={person_id:personId,email:f.get('email')||null,nickname:f.get('nick')||null,service_areas:f.getAll('area'),skills:String(f.get('skills')||'').split(',').map(x=>x.trim()).filter(Boolean),availability_days:String(f.get('days')||'').split(',').map(x=>x.trim()).filter(Boolean),service_preferences:pref,bio:f.get('bio')||null,profile_extra:extra};if(roleEdit)accountPayload.ministry_role=f.get('role');if(a){let u=await sb.from('tnt_accounts').update(accountPayload).eq('person_id',personId);if(u.error)return toast(errMsg(u.error))}else{accountPayload.ministry_role=roleEdit?f.get('role'):'Timoteo';let ins=await sb.from('tnt_accounts').insert(accountPayload);if(ins.error)return toast(errMsg(ins.error))}closeModal();await loadAll();render();toast('Perfil guardado')}}
async function uploadAvatar(pid,file){if(!file)return;let safe=file.name.replace(/[^a-zA-Z0-9._-]+/g,'_'),path=`${pid}/${Date.now()}-${safe}`;let up=await sb.storage.from('tnt-avatars').upload(path,file,{upsert:false});if(up.error)return toast(errMsg(up.error));let {data}=sb.storage.from('tnt-avatars').getPublicUrl(path);let u=await sb.from('tnt_accounts').update({avatar_url:data.publicUrl}).eq('person_id',pid);if(u.error)return toast(errMsg(u.error));await loadAll();profileModal(pid);toast('Foto actualizada')}
function availabilityModal(pid){modal(`${sheetHead('Disponibilidad puntual')}<form class="form" id="avForm"><div class="field"><label>Fecha</label><input type="date" name="date" required></div><div class="field"><label>Estado</label><select name="status"><option value="available">Disponible</option><option value="maybe">Probablemente no pueda</option><option value="unavailable">No puedo</option></select></div><div class="field"><label>Nota</label><input name="note"></div><button class="btn primary">Guardar</button></form>`);$('#avForm').onsubmit=async ev=>{ev.preventDefault();let f=new FormData(ev.target),{error}=await sb.from('tnt_availability').upsert({person_id:pid,date:f.get('date'),status:f.get('status'),note:f.get('note')||null});if(error)return toast(errMsg(error));closeModal();await loadAll();personResponsibilitiesModal(pid)}}



/* organizacion/org6a.js */
function notificationsModal(){let notes=S.notifications.filter(n=>n.person_id===currentPersonId()||n.person_id===null);modal(`${sheetHead('Notificaciones','Personales, de equipo y generales')}${(isAdmin()||isPastor())?'<div class="actions" style="margin-bottom:12px"><button class="btn primary" id="newGeneral">+ Notificación general</button></div>':''}${notes.length?`<div class="list">${notes.map(noteRow).join('')}</div>`:empty('Sin notificaciones','')}`);let own=notes.filter(n=>n.person_id===currentPersonId()&&!n.read_at).map(n=>n.id);if(own.length)sb.from('tnt_notifications').update({read_at:new Date().toISOString()}).in('id',own).then(async()=>{await loadAll()});$('#newGeneral')?.addEventListener('click',generalNotificationModal);$$('[data-note-href]').forEach(b=>b.onclick=()=>openInternal(b.dataset.noteHref))}
function generalNotificationModal(){modal(`${sheetHead('Notificación general')}<form class="form" id="notifyForm"><div class="field"><label>Título</label><input name="title" required></div><div class="field"><label>Mensaje</label><textarea name="body" required></textarea></div><button class="btn primary">Enviar</button></form>`);$('#notifyForm').onsubmit=async ev=>{ev.preventDefault();let f=new FormData(ev.target),{error}=await sb.from('tnt_notifications').insert({person_id:null,scope:'general',title:f.get('title'),body:f.get('body')});if(error)return toast(errMsg(error));closeModal();await loadAll();toast('Notificación publicada')}}
function openInternal(href){try{let u=new URL(href,location.origin);let p=u.searchParams;if(p.get('task'))return taskDetailModal(p.get('task'));if(p.get('event'))return eventDetailModal(p.get('event'))}catch{}location.href=href}

function adminUserModal(pid){let p=pBy(pid),a=aByPid(pid);if(!p||!a)return;let mods=S.moduleAccess.filter(x=>x.person_id===pid);modal(`${sheetHead('Gestionar usuario',a.nickname||p.full_name)}<form class="form" id="adminForm"><div class="formRow"><div class="field"><label>Rol TNT</label><select name="role">${ROLE_OPTIONS.map(r=>`<option ${a.ministry_role===r?'selected':''}>${r}</option>`).join('')}</select></div><div class="field"><label>Cuenta</label><select name="enabled"><option value="true" ${a.enabled?'selected':''}>Habilitada</option><option value="false" ${!a.enabled?'selected':''}>Deshabilitada</option></select></div></div><div class="card"><h3>Rol de sistema</h3><p>${a.system_role==='admin'?'Esta persona es Admin.':'Usuario normal.'}</p><div class="actions" style="margin-top:10px"><button type="button" class="btn ${a.system_role==='admin'?'danger':'primary'}" id="toggleAdmin">${a.system_role==='admin'?'Quitar Admin':'Dar Admin'}</button></div></div><div class="field"><label>Acceso a módulos</label><div class="checkList">${MODULES.map(m=>{let x=mods.find(z=>z.module===m);return `<label class="checkRow"><input type="checkbox" name="module" value="${m}" ${x?.enabled!==false?'checked':''}><span>${esc(m)}</span><select name="level_${m}"><option value="user" ${x?.access_level!=='manager'?'selected':''}>Usuario</option><option value="manager" ${x?.access_level==='manager'?'selected':''}>Gestor</option></select></label>`}).join('')}</div></div><button class="btn primary">Guardar cambios</button></form>`);$('#toggleAdmin').onclick=async()=>{let make=a.system_role!=='admin';let {error}=await sb.rpc('tnt_set_admin',{p_person:pid,p_make_admin:make});if(error)return toast(errMsg(error));closeModal();await loadAll();render();toast(make?'Admin otorgado':'Admin quitado')};$('#adminForm').onsubmit=async ev=>{ev.preventDefault();let f=new FormData(ev.target),u=await sb.from('tnt_accounts').update({ministry_role:f.get('role'),enabled:f.get('enabled')==='true'}).eq('person_id',pid);if(u.error)return toast(errMsg(u.error));for(let m of MODULES){let enabled=f.getAll('module').includes(m),access_level=f.get('level_'+m)||'user';let rr=await sb.from('tnt_module_access').upsert({person_id:pid,module:m,enabled,access_level});if(rr.error)return toast(errMsg(rr.error))}closeModal();await loadAll();render();toast('Usuario actualizado')}}



/* organizacion/org6b.js */
function templateModal(id=null){let t=S.templates.find(x=>x.id===id),items=t?S.templateItems.filter(i=>i.template_id===id).sort((a,b)=>a.sort_order-b.sort_order):[];modal(`${sheetHead(t?'Editar plantilla':'Nueva plantilla')}<form class="form" id="tplForm"><div class="field"><label>Nombre</label><input name="name" value="${esc(t?.name||'')}" required></div><div class="field"><label>Tipo</label><select name="kind"><option value="saturday" ${t?.kind==='saturday'?'selected':''}>Sábado</option><option value="event" ${t?.kind==='event'?'selected':''}>Evento</option><option value="camp" ${t?.kind==='camp'?'selected':''}>Campamento</option></select></div><div class="field"><label>Descripción</label><textarea name="description">${esc(t?.description||'')}</textarea></div><button class="btn primary">Guardar plantilla</button></form>${t?`<div class="sectionHead"><h2>Ítems</h2><button class="btn small primary" id="addTplItem">+ Ítem</button></div><div class="list">${items.map((i,idx)=>`<div class="rowCard"><div class="ico">${esc(i.icon||'✓')}</div><div><b>${esc(i.title)}</b><div class="tiny">${esc(i.task_type)}</div></div><div class="actions"><button class="btn small" data-tpl-move="${i.id}" data-dir="-1">↑</button><button class="btn small" data-tpl-move="${i.id}" data-dir="1">↓</button><button class="btn small danger" data-tpl-del="${i.id}">×</button></div></div>`).join('')}</div><div class="actions" style="margin-top:15px"><button class="btn danger" id="deleteTemplate">Eliminar plantilla</button></div>`:''}`);$('#tplForm').onsubmit=async ev=>{ev.preventDefault();let f=new FormData(ev.target),payload={name:f.get('name'),kind:f.get('kind'),description:f.get('description')||null,created_by:t?.created_by||currentPersonId()};let res=t?await sb.from('tnt_templates').update(payload).eq('id',t.id).select().single():await sb.from('tnt_templates').insert(payload).select().single();if(res.error)return toast(errMsg(res.error));await loadAll();templateModal(res.data.id);toast('Plantilla guardada')};$('#addTplItem')?.addEventListener('click',()=>templateItemModal(t.id,items.length));$$('[data-tpl-del]').forEach(b=>b.onclick=async()=>{await sb.from('tnt_template_items').delete().eq('id',b.dataset.tplDel);await loadAll();templateModal(t.id)});$$('[data-tpl-move]').forEach(b=>b.onclick=()=>moveTemplateItem(t.id,b.dataset.tplMove,Number(b.dataset.dir)));$('#deleteTemplate')?.addEventListener('click',async()=>{if(!confirm('¿Eliminar esta plantilla?'))return;let {error}=await sb.from('tnt_templates').delete().eq('id',t.id);if(error)return toast(errMsg(error));closeModal();await loadAll();render()})}
function templateItemModal(templateId,order){modal(`${sheetHead('Agregar ítem')}<form class="form" id="tplItemForm"><div class="formRow"><div class="field"><label>Nombre</label><input name="title" required></div><div class="field"><label>Ícono</label><input name="icon" value="✓"></div></div><div class="field"><label>Tipo</label><select name="type"><option value="simple">Simple</option><option value="complex">Compleja</option></select></div><div class="field"><label>Descripción</label><textarea name="description"></textarea></div><button class="btn primary">Agregar</button></form>`);$('#tplItemForm').onsubmit=async ev=>{ev.preventDefault();let f=new FormData(ev.target),{error}=await sb.from('tnt_template_items').insert({template_id:templateId,title:f.get('title'),icon:f.get('icon')||'✓',task_type:f.get('type'),description:f.get('description')||null,sort_order:order});if(error)return toast(errMsg(error));await loadAll();templateModal(templateId)}}
async function moveTemplateItem(templateId,id,dir){let items=S.templateItems.filter(i=>i.template_id===templateId).sort((a,b)=>a.sort_order-b.sort_order),idx=items.findIndex(i=>i.id===id),other=items[idx+dir];if(idx<0||!other)return;let cur=items[idx];await Promise.all([sb.from('tnt_template_items').update({sort_order:other.sort_order}).eq('id',cur.id),sb.from('tnt_template_items').update({sort_order:cur.sort_order}).eq('id',other.id)]);await loadAll();templateModal(templateId)}

// Eventos globales posteriores al render





function openDeepLink(){const q=new URLSearchParams(location.search);if(q.get('task')&&taskBy(q.get('task')))taskDetailModal(q.get('task'));else if(q.get('event')&&eventBy(q.get('event')))eventDetailModal(q.get('event'));else if(q.get('person')&&pBy(q.get('person')))personResponsibilitiesModal(q.get('person'));}

function avatars(ids,max=5){return U.avatarStack(ids,S.people,S.accounts,currentPersonId(),max);}

function personalTasks(){return S.tasks.filter(t=>myAssignment(t)&&!U.completed(t)).sort((a,b)=>(a.planned_start||a.due_at||eventBy(a.event_id)?.start_date||'9999').localeCompare(b.planned_start||b.due_at||eventBy(b.event_id)?.start_date||'9999'));}

function personalItems(){const ids=new Set(S.responsibles.filter(r=>r.person_id===currentPersonId()).map(r=>r.item_id));return S.items.filter(i=>ids.has(i.id)&&i.run_status!=='done'&&(!i.task_id||!personalTasks().some(t=>t.id===i.task_id))&&dayBy(i.day_id)?.date>=today());}

function taskMatches(t){const mine=Boolean(myAssignment(t)),d=(t.planned_start||t.due_at)?U.dateKey(t.planned_start||t.due_at):eventBy(t.event_id)?.start_date;const f=S.activityFilter||'all';if(f==='mine'&&!mine)return false;if(f==='today'&&d!==today())return false;if(f==='upcoming'&&(!d||d<today()||U.completed(t)))return false;if(f==='unread'&&(!mine||myAssignment(t).assignment_status!=='assigned'))return false;if(f==='answer'&&(!mine||!['assigned','read'].includes(myAssignment(t).assignment_status)))return false;return !S.activityEvent||t.event_id===S.activityEvent;}

function viewActivities(){const tasks=S.tasks.filter(taskMatches).sort((a,b)=>Number(Boolean(myAssignment(b)))-Number(Boolean(myAssignment(a)))||(a.due_at||'9999').localeCompare(b.due_at||'9999'));return `<div class="sectionHead"><div><h2>Actividades del equipo</h2><p>Las tuyas están destacadas. Todas tienen su equipo a la vista.</p></div>${S.events.some(e=>canManageEvent(e.id))?'<button class="btn primary" data-new-task>'+U.icon('plus')+' Tarea</button>':''}</div><div class="activity-tools"><div class="filters">${[['all','Todas'],['mine','Mías'],['today','Hoy'],['upcoming','Próximas'],['unread','No leídas'],['answer','Necesitan respuesta']].map(([k,l])=>`<button data-filter="${k}" class="${(S.activityFilter||'all')===k?'on':''}">${l}</button>`).join('')}</div><label class="sr-only" for="activity-event">Filtrar por evento</label><select class="control" id="activity-event"><option value="">Todos los eventos</option>${S.events.map(e=>`<option value="${e.id}" ${S.activityEvent===e.id?'selected':''}>${esc(e.name)} · ${fmtShort(e.start_date)}</option>`).join('')}</select></div><div class="activities-grid">${tasks.map(t=>taskRow(t,myAssignment(t))).join('')||empty('No hay actividades con este filtro','Probá con otra fecha o evento.')}</div>`;}

function viewCalendar(){const selected=S.calendarDate||today(),month=S.calendarMonth||selected.slice(0,7)+'-01',mode=S.calendarMode||'month',start=new Date(month+'T12:00:00Z'),days=new Date(Date.UTC(start.getUTCFullYear(),start.getUTCMonth()+1,0)).getUTCDate(),offset=(start.getUTCDay()+6)%7;let cells=Array.from({length:offset},()=>'<span></span>');for(let d=1;d<=days;d++){const date=month.slice(0,8)+String(d).padStart(2,'0'),events=S.events.filter(e=>e.start_date<=date&&e.end_date>=date&&e.status!=='cancelled'),mine=events.some(e=>eventMembers(e.id).some(m=>m.person_id===currentPersonId()));cells.push(`<button class="cal-day ${date===selected?'selected':''} ${date===today()?'today':''}" data-cal-date="${date}" aria-label="${fmtDate(date)}: ${events.length} eventos" aria-pressed="${date===selected}">${d}${events.length?'<span class="cal-dots"><i></i>'+(mine?'<i class="personal"></i>':'')+'</span>':''}</button>`);}const def=S.settings.find(s=>s.key==='organization_defaults')?.value||{};return `<div class="sectionHead"><h2>Calendario</h2><div class="actions"><button class="btn" data-cal-today>Hoy</button>${isAdmin()?'<button class="btn" data-recurring-settings>'+U.icon('settings')+' Sábados TNT</button>':''}</div></div><div class="cal-modes">${[['month','Mes'],['week','Semana'],['day','Día']].map(([k,l])=>`<button data-cal-mode="${k}" class="${mode===k?'on':''}">${l}</button>`).join('')}</div><div class="calendar-layout ${mode!=='month'?'wide-agenda':''}">${mode==='month'?`<section class="calendar-panel"><div class="calendar-top"><button data-month-step="-1" aria-label="Mes anterior">${U.icon('back')}</button><h3>${U.date(month,{month:'long',year:'numeric'})}</h3><button data-month-step="1" aria-label="Mes siguiente">${U.icon('arrow')}</button></div><div class="weekdays">${['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(x=>'<span>'+x+'</span>').join('')}</div><div class="calendar-grid">${cells.join('')}</div><div class="calendar-key"><span><i></i> Hay actividad</span><span>${def.auto_saturdays!==false?'Sábados automáticos':'Sábados automáticos desactivados'}</span></div></section>`:''}<section class="calendar-agenda">${mode==='week'?weekAgenda(selected):`<div class="sectionHead"><h2>${fmtDate(selected)}</h2>${isAdmin()||isPastor()?'<button class="btn primary" data-calendar-add>'+U.icon('plus')+' Actividad</button>':''}</div>${dateAgenda(selected)}`}</section></div>`;}

function weekAgenda(date){const d=new Date(date+'T12:00:00Z'),first=U.addDays(date,-((d.getUTCDay()+6)%7));return `<div class="week-controls"><button class="btn" data-week-step="-7">${U.icon('back')} Anterior</button><span>${fmtShort(first)} — ${fmtShort(U.addDays(first,6))}</span><button class="btn" data-week-step="7">Siguiente ${U.icon('arrow')}</button></div><div class="week-agenda">${Array.from({length:7},(_,i)=>{const key=U.addDays(first,i);return `<div class="week-day"><h3><button data-cal-date="${key}" class="plain-date">${fmtDate(key)}</button></h3>${dateAgenda(key)}</div>`;}).join('')}</div>`;}

function dateAgenda(date){const events=S.events.filter(e=>e.start_date<=date&&e.end_date>=date&&e.status!=='cancelled'),dayIds=new Set(S.days.filter(d=>d.date===date).map(d=>d.id)),items=S.items.filter(i=>dayIds.has(i.day_id)).sort((a,b)=>(a.starts_at||'99').localeCompare(b.starts_at||'99'));return `${events.map(e=>`<div class="agenda-event"><button data-event-open="${e.id}"><b>${esc(e.name)}</b><small>${esc(e.location||'TNT')}</small></button>${canManageEvent(e.id)?`<button class="btn small" data-add-on-date="${date}" data-event-id="${e.id}" aria-label="Agregar actividad a ${esc(e.name)}">${U.icon('plus')}</button>`:''}</div>`).join('')}<div class="agenda-list">${items.map(i=>scheduleItemRow(eventBy(dayBy(i.day_id).event_id),i)).join('')||(!events.length?empty('Sin actividades para este día',''): '<p class="tiny">El evento todavía no tiene horarios cargados.</p>')}</div>`;}

function viewBrief(){const tasks=personalTasks();return `<div class="sectionHead"><h2>Mi resumen de servicio</h2><button class="btn" data-print>${U.icon('download')} Guardar PDF</button></div><div class="briefing-list">${tasks.map(t=>`<article class="card"><h3>${esc(t.title)}</h3><p>${esc(eventBy(t.event_id)?.name||'TNT')} · ${esc(t.planned_start||t.due_at?U.date(t.planned_start||t.due_at,{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'}):fmtDate(eventBy(t.event_id)?.start_date))}</p><p>${esc(t.description||'')}</p>${t.materials?'<p><b>Materiales:</b> '+esc(t.materials)+'</p>':''}${avatars(taskPeople(t.id))}<div class="chips">${assignChip(myAssignment(t).assignment_status)}</div></article>`).join('')||empty('Sin responsabilidades pendientes','')}${personalItems().map(i=>scheduleItemRow(eventBy(dayBy(i.day_id).event_id),i)).join('')}</div>`;}

function viewFiles(){return `<div class="sectionHead"><h2>Archivos y recursos</h2>${isAdmin()||isPastor()?'<button class="btn primary" data-add-resource>'+U.icon('plus')+' Recurso</button>':''}</div><div class="grid g2">${S.files.filter(f=>!f.module||f.module==='organizacion').map(f=>`<a class="resource-card" href="${esc(U.safeUrl(f.url))}" target="_blank" rel="noopener noreferrer">${U.icon('file')}<div><h3>${esc(f.title)}</h3><p>${esc(f.folder||'General')}</p></div>${U.icon('up')}</a>`).join('')||empty('Todavía no hay recursos compartidos','Agregá documentos, videos o enlaces para tu equipo.')}</div>`;}

async function syncSaturdays(){if(!(isAdmin()||isPastor()))return;const from=S.calendarMonth&&S.calendarMonth>today()?S.calendarMonth:today(),to=U.addDays(from,92);const r=await sb.rpc('tnt_sync_saturdays',{p_from:from,p_to:to});if(r.error){console.warn('Sábados TNT',r.error);S.recurringError='No pudimos actualizar los sábados automáticos: '+errMsg(r.error);}else S.recurringError='';}

function bindNew(){
 $$('[data-open-chat]').forEach(b=>b.onclick=()=>location.href='/chat/');$$('[data-print]').forEach(b=>b.onclick=()=>window.print());$$('[data-reload]').forEach(b=>b.onclick=async()=>{await loadAll();render();});$$('[data-filter]').forEach(b=>b.onclick=()=>{S.activityFilter=b.dataset.filter;render();});$('#activity-event')?.addEventListener('change',e=>{S.activityEvent=e.target.value;render();});$$('[data-past]').forEach(b=>b.onclick=()=>{S.showPast=!S.showPast;render();});$$('[data-new-task]').forEach(b=>b.onclick=chooseTaskEvent);
 $$('[data-cal-date]').forEach(b=>b.onclick=()=>{S.calendarDate=b.dataset.calDate;S.calendarMonth=S.calendarDate.slice(0,7)+'-01';if(S.calendarMode==='week')S.calendarMode='day';render();});$$('[data-cal-mode]').forEach(b=>b.onclick=()=>{S.calendarMode=b.dataset.calMode;render();});$$('[data-cal-today]').forEach(b=>b.onclick=()=>{S.calendarDate=today();S.calendarMonth=today().slice(0,7)+'-01';render();});$$('[data-month-step]').forEach(b=>b.onclick=async()=>{const d=new Date((S.calendarMonth||today().slice(0,7)+'-01')+'T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+Number(b.dataset.monthStep));S.calendarMonth=d.toISOString().slice(0,10);S.calendarDate=S.calendarMonth;await syncSaturdays();await loadAll();render();});$$('[data-week-step]').forEach(b=>b.onclick=()=>{S.calendarDate=U.addDays(S.calendarDate||today(),Number(b.dataset.weekStep));render();});$$('[data-recurring-settings]').forEach(b=>b.onclick=recurringSettings);$$('[data-calendar-add]').forEach(b=>b.onclick=calendarAdd);$$('[data-add-on-date]').forEach(b=>b.onclick=()=>addCalendarActivity(b.dataset.eventId,b.dataset.addOnDate));$$('[data-item-open]').forEach(b=>b.onclick=()=>scheduleItemDetailModal(b.dataset.itemOpen));$$('[data-add-resource]').forEach(b=>b.onclick=addResource);
}

function chooseTaskEvent(){const events=S.events.filter(e=>canManageEvent(e.id));const o=U.modal('¿Para qué evento?',`<div class="tnt-form"><label for="new-task-event">Evento</label><select id="new-task-event">${events.map(e=>`<option value="${e.id}">${esc(e.name)} · ${fmtShort(e.start_date)}</option>`).join('')}</select><button class="tnt-button primary" id="continue-task">Continuar</button></div>`);o.querySelector('#continue-task').onclick=()=>{const id=o.querySelector('select').value;o.remove();if(id)taskEditModal(null,id);};}

function calendarAdd(){const date=S.calendarDate||today(),events=S.events.filter(e=>e.start_date<=date&&e.end_date>=date&&canManageEvent(e.id));if(events.length===1)return addCalendarActivity(events[0].id,date);const o=U.modal('Agregar actividad',`<div class="tnt-form">${events.length?`<label for="cal-event">Evento</label><select id="cal-event">${events.map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select><button class="tnt-button primary" id="cal-choose">Agregar a este evento</button>`:'<p>Primero creá el evento de este día.</p>'}<button class="tnt-button" id="cal-new">Crear evento</button></div>`);o.querySelector('#cal-choose')?.addEventListener('click',()=>{const id=o.querySelector('select').value;o.remove();addCalendarActivity(id,date);});o.querySelector('#cal-new').onclick=()=>{o.remove();eventCreateModal();const f=$('#eventForm');if(f){f.elements.start.value=date;f.elements.end.value=date;}};}

async function addCalendarActivity(eventId,date){S.selectedEvent=eventId;let day=S.days.find(d=>d.event_id===eventId&&d.date===date);if(!day){const r=await sb.from('tnt_schedule_days').insert({event_id:eventId,date,label:fmtDate(date),sort_order:eventDays(eventId).length}).select().single();if(r.error)return U.toast(r.error.message,true);day=r.data;S.days.push(day);}S.selectedDay=day.id;scheduleItemModal();}

function recurringSettings(){
 if(!isAdmin())return U.toast('La configuración general la administra un Admin TNT.');
 const old=S.settings.find(s=>s.key==='organization_defaults')?.value||{},rows=(old.default_activities||['Bienvenida','Dinámica','Ofrenda','Ministración','Palabra','Merienda','Cierre']).map(a=>typeof a==='string'?{title:a,minutes:30,enabled:true}:{...a}),excluded=[...(old.saturday_excluded||[])];
 const o=U.modal('Sábados TNT',`<form class="tnt-form" id="recurring-form"><label class="switch-row"><input name="enabled" type="checkbox" ${old.auto_saturdays!==false?'checked':''}>Programar sábados automáticamente</label><div class="tnt-form-grid"><div><label for="sat-time">Hora de inicio</label><input id="sat-time" name="time" type="time" value="${esc(old.saturday_start||'18:30')}" required></div><div><label for="sat-frequency">Frecuencia</label><select id="sat-frequency" name="frequency"><option value="weekly">Todos los sábados</option><option value="biweekly" ${old.saturday_frequency==='biweekly'?'selected':''}>Cada dos semanas</option><option value="first" ${old.saturday_frequency==='first'?'selected':''}>Primer sábado del mes</option></select></div><div><label for="sat-from">Desde</label><input id="sat-from" name="from" type="date" value="${esc(old.saturday_from||today())}" required></div><div><label for="sat-until">Hasta (opcional)</label><input id="sat-until" name="until" type="date" value="${esc(old.saturday_until||'')}"></div></div><div class="sectionHead"><h3>Actividades predeterminadas</h3><button type="button" class="tnt-button" id="sat-add">Agregar</button></div><p>Activá las que uses y acomodá su orden. La duración está en minutos.</p><div id="sat-rows"></div><div><label for="sat-exclude-date">Saltear una fecha</label><div class="actions"><input id="sat-exclude-date" type="date"><button type="button" class="tnt-button" id="sat-exclude-add">Agregar excepción</button></div><div id="sat-exclusions" class="chips"></div></div><p>Se preparan los próximos tres meses al abrir Organización. Los cambios se aplican a fechas nuevas. Los eventos guardados se conservan y se editan desde el calendario, incluso al apagar esta opción.</p><button class="tnt-button primary" type="submit">Guardar configuración</button><div role="alert" id="sat-error"></div></form>`,true);
 const readRows=()=>o.querySelectorAll('[data-sat-row]').forEach(el=>{const a=rows[Number(el.dataset.satRow)];a.title=el.querySelector('[data-title]').value.trim();a.minutes=Number(el.querySelector('[data-minutes]').value);a.enabled=el.querySelector('[data-enabled]').checked;});
 const paint=()=>{o.querySelector('#sat-rows').innerHTML=rows.map((a,i)=>`<div class="sat-config-row" data-sat-row="${i}"><input type="checkbox" data-enabled aria-label="Activar ${esc(a.title)}" ${a.enabled!==false?'checked':''}><input data-title aria-label="Nombre de la actividad ${i+1}" value="${esc(a.title)}" required maxlength="100"><label><input data-minutes type="number" min="1" max="720" value="${a.minutes||30}" aria-label="Duración de la actividad ${i+1}" required><small>min</small></label><div class="actions"><button type="button" class="btn icon-only" data-move="${i}|-1" aria-label="Subir actividad" ${i===0?'disabled':''}>↑</button><button type="button" class="btn icon-only" data-move="${i}|1" aria-label="Bajar actividad" ${i===rows.length-1?'disabled':''}>↓</button><button type="button" class="btn icon-only" data-remove="${i}" aria-label="Quitar actividad">×</button></div></div>`).join('');o.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>{readRows();const [i,n]=b.dataset.move.split('|').map(Number);[rows[i],rows[i+n]]=[rows[i+n],rows[i]];paint();});o.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{readRows();rows.splice(Number(b.dataset.remove),1);paint();});o.querySelector('#sat-exclusions').innerHTML=excluded.map((d,i)=>`<button class="btn small" type="button" data-exclusion="${i}">${esc(fmtShort(d))} ×</button>`).join('');o.querySelectorAll('[data-exclusion]').forEach(b=>b.onclick=()=>{readRows();excluded.splice(Number(b.dataset.exclusion),1);paint();});};
 paint();o.querySelector('#sat-add').onclick=()=>{readRows();rows.push({title:'Nueva actividad',minutes:20,enabled:true});paint();};o.querySelector('#sat-exclude-add').onclick=()=>{const d=o.querySelector('#sat-exclude-date').value;if(d&&!excluded.includes(d)){readRows();excluded.push(d);paint();}};
 o.querySelector('form').onsubmit=async e=>{e.preventDefault();readRows();const f=new FormData(e.target),b=e.target.querySelector('[type=submit]');b.disabled=true;try{if(rows.length>30||rows.some(a=>!a.title||!Number.isInteger(a.minutes)||a.minutes<1||a.minutes>720))throw Error('Revisá los nombres y duraciones. Podés agregar hasta 30 actividades.');if(f.get('enabled')&&!rows.some(a=>a.enabled))throw Error('Activá al menos una actividad.');const [h,m]=f.get('time').split(':').map(Number);if(h*60+m+rows.filter(a=>a.enabled).reduce((s,a)=>s+a.minutes,0)>1440)throw Error('Las actividades deben terminar antes de medianoche.');if(f.get('until')&&f.get('until')<f.get('from'))throw Error('La fecha final debe ser posterior al inicio.');const value={...old,auto_saturdays:f.get('enabled')==='on',saturday_start:f.get('time'),saturday_frequency:f.get('frequency'),saturday_from:f.get('from'),saturday_until:f.get('until')||null,saturday_excluded:excluded,default_activities:rows};const r=await sb.from('tnt_settings').upsert({key:'organization_defaults',value,updated_by:currentPersonId()},{onConflict:'key'}).select().single();if(r.error)throw r.error;await loadAll();await syncSaturdays();await loadAll();if(S.recurringError)throw Error(S.recurringError);o.remove();render();U.toast('Configuración guardada');}catch(err){o.querySelector('#sat-error').textContent=err.message;}finally{b.disabled=false;}};
}

async function openActivityChat(taskId,eventId){try{const r=await sb.rpc('tnt_open_activity_chat',{p_task:taskId||null,p_event:eventId||null});if(r.error)throw r.error;location.href='/chat/?thread='+encodeURIComponent(r.data);}catch(e){U.toast(e.message||'No pudimos abrir el chat.',true);}}

function addResource(){const o=U.modal('Compartir recurso','<form class="tnt-form"><div><label for="resource-title">Nombre</label><input id="resource-title" name="title" required></div><div><label for="resource-url">Enlace</label><input id="resource-url" name="url" type="url" required placeholder="https://"></div><button class="tnt-button primary" type="submit">Guardar recurso</button><div role="alert"></div></form>');o.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),url=U.safeUrl(f.get('url'));if(!url)return;const r=await sb.from('tnt_library_items').insert({title:String(f.get('title')).trim(),url,folder:'Organización',module:'organizacion',uploaded_by:currentPersonId()}).select().single();if(r.error)return o.querySelector('[role=alert]').textContent=r.error.message;o.remove();await loadAll();render();};}

const originalTaskDetail=taskDetailModal;taskDetailModal=async function(id){await originalTaskDetail(id);const host=$('#modal .sheet');if(!host)return;const b=document.createElement('button');b.className='btn primary context-chat';b.innerHTML=U.icon('chat')+' Chat de esta tarea';b.onclick=()=>openActivityChat(id,null);if(myAssignment(taskBy(id))||canManageEvent(taskBy(id).event_id))host.querySelector('.sheetHead').after(b);if(canManageEvent(taskBy(id).event_id)){const r=document.createElement('button');r.className='btn';r.textContent='Buscar reemplazo';r.onclick=()=>replacementCandidates(id);host.querySelector('.sheetHead').after(r);}};
const originalEventDetail=eventDetailModal;eventDetailModal=function(id){originalEventDetail(id);const host=$('#modal .sheet');if(!host)return;const actions=document.createElement('div');actions.className='actions event-context';actions.innerHTML='<button class="btn primary" data-event-schedule>Ver cronograma y grupos</button><button class="btn" data-event-chat>Chat del evento</button>';host.querySelector('.sheetHead').after(actions);actions.querySelector('[data-event-schedule]').onclick=()=>{closeModal();S.selectedEvent=id;S.selectedDay=eventDays(id)[0]?.id;S.view='schedule';render();};actions.querySelector('[data-event-chat]').onclick=()=>openActivityChat(null,id);const e=eventBy(id);const c=S.checkins.find(x=>x.event_id===id&&x.person_id===currentPersonId()&&!x.checked_out_at);const options=[['Modo pantalla',()=>projectEvent(id)],...((e.start_date<=today()&&e.end_date>=today())?[[c?'Registrar salida':'Ya llegué',()=>checkin(id)]]:[]),...(canManageEvent(id)?[['Editar evento',()=>editEvent(id)]]:[]),...((isAdmin()||isPastor())?[['Duplicar',()=>duplicateEvent(id)]]:[])];options.forEach(([label,fn])=>{const b=document.createElement('button');b.className='btn';b.textContent=label;b.onclick=fn;actions.append(b);});};
async function checkin(eid){const c=S.checkins.find(x=>x.event_id===eid&&x.person_id===currentPersonId()&&!x.checked_out_at);const r=c?await sb.from('tnt_checkins').update({checked_out_at:new Date().toISOString()}).eq('id',c.id).select().single():await sb.from('tnt_checkins').upsert({event_id:eid,person_id:currentPersonId(),checked_in_at:new Date().toISOString(),checked_out_at:null},{onConflict:'event_id,person_id'}).select().single();if(r.error)return U.toast(r.error.message,true);await loadAll();render();eventDetailModal(eid);U.toast(c?'Salida registrada':'¡Ya estás presente!');}
function duplicateEvent(id){const e=eventBy(id),o=U.modal('Duplicar evento',`<form class="tnt-form"><div><label for="copy-name">Nombre</label><input id="copy-name" name="name" value="${esc(e.name+' · copia')}" required></div><div><label for="copy-date">Nueva fecha de inicio</label><input id="copy-date" name="date" type="date" value="${e.start_date}" required></div><label class="switch-row"><input name="team" type="checkbox">Copiar también participantes y responsables</label><p>Se copian tareas, subtareas, checklist, enlaces y cronograma. Los estados vuelven a pendiente.</p><button class="tnt-button primary" type="submit">Crear copia</button><p role="alert"></p></form>`);o.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.target),b=ev.target.querySelector('[type=submit]');b.disabled=true;const r=await sb.rpc('tnt_copy_event',{p_event:id,p_name:f.get('name'),p_date:f.get('date'),p_team:f.get('team')==='on'});if(r.error){b.disabled=false;return o.querySelector('[role=alert]').textContent=r.error.message;}o.remove();await loadAll();render();eventDetailModal(r.data);};}
function editEvent(id){const e=eventBy(id),o=U.modal('Editar evento',`<form class="tnt-form"><div><label for="ev-name">Nombre</label><input id="ev-name" name="name" value="${esc(e.name)}" required></div><div><label for="ev-description">Descripción</label><textarea id="ev-description" name="description">${esc(e.description||'')}</textarea></div><div><label for="ev-location">Lugar</label><input id="ev-location" name="location" value="${esc(e.location||'')}"></div><div class="tnt-form-grid"><div><label for="ev-start">Desde</label><input id="ev-start" type="date" name="start" value="${e.start_date}" required></div><div><label for="ev-end">Hasta</label><input id="ev-end" type="date" name="end" value="${e.end_date}" required></div></div><div><label for="ev-status">Estado</label><select id="ev-status" name="status">${[['planning','En preparación'],['confirmed','Confirmado'],['live','En curso'],['completed','Terminado'],['cancelled','Cancelado']].map(([v,l])=>`<option value="${v}" ${e.status===v?'selected':''}>${l}</option>`).join('')}</select></div><p>Para trasladar todo el cronograma a otra fecha, usá Duplicar evento. Acá podés ajustar el intervalo manteniendo los días ya planificados dentro de él.</p><button class="tnt-button primary" type="submit">Guardar evento</button><p role="alert"></p></form>`);o.querySelector('form').onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.target),start=f.get('start'),end=f.get('end');if(end<start)return o.querySelector('[role=alert]').textContent='Revisá el intervalo de fechas.';if(eventDays(id).some(d=>d.date&&(d.date<start||d.date>end)))return o.querySelector('[role=alert]').textContent='Hay actividades fuera de ese intervalo. Ampliá las fechas o usá Duplicar evento.';const r=await sb.from('tnt_events').update({name:f.get('name').trim(),description:f.get('description'),location:f.get('location'),start_date:start,end_date:end,status:f.get('status')}).eq('id',id).select().single();if(r.error)return o.querySelector('[role=alert]').textContent=r.error.message;o.remove();await loadAll();render();eventDetailModal(id);};}
function projectEvent(id){const e=eventBy(id),d=document.createElement('dialog');d.className='org-projection';document.body.append(d);const paint=()=>{d.innerHTML=`<header><div><span class="eyebrow">TNT · MODO PANTALLA</span><h1>${esc(e.name)}</h1><p>${esc(e.location||'')} · ${fmtDate(e.start_date)}</p></div><button class="btn" id="projection-close">Cerrar</button></header>${eventDays(id).map(day=>`<h2>${esc(day.label)} · ${fmtShort(day.date)}</h2><div class="projection-list">${dayItems(day.id).map(i=>`<article class="${i.run_status==='live'?'is-live':''}"><b>${fmtTime(i.starts_at)}</b><div><h3>${esc(i.title)}</h3><p>${itemPeople(i.id).map(pid=>esc(displayName(pid))).join(' · ')||'Sin responsables asignados'}</p></div><span>${RUN_LABEL[i.run_status||'pending']}</span></article>`).join('')}</div>`).join('')||'<p>Este evento todavía no tiene actividades.</p>'}`;d.querySelector('#projection-close').onclick=()=>d.close();};paint();d.showModal();const timer=setInterval(async()=>{if(document.hidden)return;const days=eventDays(id).map(x=>x.id);if(!days.length)return;const r=await sb.from('tnt_schedule_items').select('*').in('day_id',days);if(!r.error){S.items=S.items.filter(i=>!days.includes(i.day_id)).concat(r.data||[]);paint();}},10000);d.addEventListener('close',()=>{clearInterval(timer);d.remove();});}
function replacementCandidates(taskId){const target=taskBy(taskId),active=new Set(taskPeople(taskId)),day=target.planned_start?U.dateKey(target.planned_start):eventBy(target.event_id)?.start_date;const overlap=(a,b)=>{if(!a.planned_start||!b.planned_start)return false;const as=Date.parse(a.planned_start),bs=Date.parse(b.planned_start);return as<bs+(b.duration_minutes||60)*60000&&bs<as+(a.duration_minutes||60)*60000;};const rows=S.people.filter(p=>aByPid(p.id)?.enabled!==false&&!active.has(p.id)).map(p=>{const tasks=S.tasks.filter(t=>taskPeople(t.id).includes(p.id)&&!U.completed(t.status)),av=S.availability.find(a=>a.person_id===p.id&&a.date===day),unavailable=av?.status==='unavailable',conflict=tasks.some(t=>t.id!==taskId&&overlap(t,target));return{p,load:tasks.length,unavailable,conflict,known:!!av,score:(unavailable?1000:0)+(conflict?500:0)+tasks.length};}).sort((a,b)=>a.score-b.score);const o=U.modal('Buscar reemplazo',`<p>Ordenados por disponibilidad registrada y tareas activas. Revisá la propuesta antes de asignar.</p>${rows.slice(0,20).map(x=>`<div class="chat-participant replacement-row">${avatarHtml(x.p.id)}<div><b>${esc(displayName(x.p.id))}</b><small>${x.unavailable?'No disponible':x.conflict?'Coincide con otra tarea':x.load+' tareas activas'}${!x.known?' · Disponibilidad sin confirmar':''}</small></div><button class="btn" data-candidate="${x.p.id}">Asignar</button></div>`).join('')||'<p>No hay más personas disponibles en el equipo.</p>'}`);o.querySelectorAll('[data-candidate]').forEach(b=>b.onclick=async()=>{const x=rows.find(x=>x.p.id===b.dataset.candidate);if((x.unavailable||x.conflict)&&!confirm('Hay una dificultad de disponibilidad. ¿Querés asignar igual?'))return;const r=await sb.from('tnt_task_assignees').insert({task_id:taskId,person_id:x.p.id,assignment_status:'assigned'}).select().single();if(r.error)return U.toast(r.error.message,true);o.remove();await loadAll();render();taskDetailModal(taskId);});}
const originalItemDetail=scheduleItemDetailModal;scheduleItemDetailModal=function(id){originalItemDetail(id);const i=S.items.find(x=>x.id===id),d=dayBy(i?.day_id),host=$('#modal .sheet');if(!host||!d)return;S.selectedDay=d.id;S.selectedEvent=d.event_id;if(canManageEvent(d.event_id)){const row=document.createElement('div');row.className='actions live-controls';for(const [status,label] of Object.entries(RUN_LABEL)){const b=document.createElement('button');b.className='btn '+(i.run_status===status?'primary':'');b.textContent=label;b.onclick=async()=>{const r=await sb.from('tnt_schedule_items').update({run_status:status}).eq('id',id).select().single();if(r.error)return U.toast(r.error.message,true);await loadAll();render();scheduleItemDetailModal(id);};row.append(b);}host.querySelector('.sheetHead').after(row);}};
boot();